#include "ringbuf.h"
#include <stdlib.h>
#include <string.h>

struct ringbuf {
    uint8_t *storage;
    size_t capacity;
    size head;
    size tail;
};

rb_create(size_t capacity)
{
    if (capacity == 0)
        return NULL;

    rb = malloc(sizeof(*rb));
    if (!rb)
        return NULL;

    rb->storage = malloc(capacity);
    if (!rb->storage) {
        free(rb);
        return NULL;
    }

    rb->capacity = capacity;
    rb->head = 0;
    rb->tail = 0;
    return rb;
}

void rb_destroy(ringbuf_t *rb)
{
    if (!rb)
        return;
    free(rb->storage);
    free(rb);
}

static size_t rb_free(const ringbuf_t *rb)
{
    if (rb->head >= rb->tail)
        return rb->capacity - rb->head + rb->tail - 1;
    else
        return rb->tail - rb->head - 1;
}

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len)
{
    if (!rb || !data || len == 0)
        return 0;

    size_t avail = rb_free(rb);
    if (avail == 0)
        return 0;

    size_t n = len < avail ? len : avail;
    size_t to_first = rb->capacity - rb->head;
    size_t copy_first = n < to_first ? n : to_first;

    memcpy(rb->storage + rb->head, data, copy_first);
    rb->head += copy_first;
    if (rb->head == rb->capacity)
        rb->head = 0;

    if (n > copy_first) {
        size_t remaining = n - copy_first;
        memcpy(rb->storage, data + copy_first, remaining);
        rb->head += remaining;
    }

    return n;
}

size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out || len == 0)
        return 0;

    size_t sz = rb_size(rb);
    if (sz == 0)
        return 0;

    size_t n = len < sz ? len : sz;
    size_t to_first = rb->capacity - rb->tail;
    size_t copy_first = n < to_first ? n : to_first;

    memcpy(out, rb->storage + rb->tail, copy_first);
    rb->tail += copy_first;
    if (rb->tail == rb->capacity)
        rb->tail = 0;

    if (n > copy_first) {
        size_t remaining = n - copy_first;
        memcpy(out + copy_first, rb->storage, remaining);
        rb->tail += remaining;
    }

    return n;
}

size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out || len == 0)
        return 0;

    size_t sz = rb_size(rb);
    if (sz == 0)
        return 0;

    size_t n = len < sz ? len : sz;
    size_t to_first = rb->capacity - rb->tail;
    size_t copy_first = n < to_first ? n : to_first;

    memcpy(out, rb->storage + rb->tail, copy_first);

    if (n > copy_first) {
        size_t remaining = n - copy_first;
        memcpy(out + copy_first, rb->storage, remaining);
    }

    return n;
}

size_t rb_size(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    if (rb->head >= rb->tail)
        return rb->head - rb->tail;
    else
        return rb->capacity - rb->tail + rb->head;
}

size_t rb_capacity(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->capacity;
}

void rb_clear(ringbuf_t *rb)
{
    if (!rb)
        return;
    rb->head = 0;
    rb->tail = 0;
}

